from math import prod

def solve(inputs: dict) -> float:
    mods = [467, 1783, 937, 1229, 1447]
    rems = [330, 1602, 14, 263, 411]
    x = 0
    M = 1
    for m, r in zip(mods, rems):
        # solve x ≡ r mod m, given current x ≡ x mod M
        # find t s.t. x + M*t ≡ r mod m
        # since moduli are pairwise coprime, inverse exists
        a = M % m
        # extended gcd for inverse of a mod m
        def egcd(a,b):
            if b==0:
                return (a,1,0)
            g,s,t = egcd(b,a%b)
            return (g,t,s-(a//b)*t)
        g, inv, _ = egcd(a, m)
        inv %= m
        t = ((r - x) % m) * inv % m
        x += M * t
        M *= m
    return float(x)

