def solve(inputs: dict) -> float:
    M = inputs.get('M')
    n = inputs.get('n')
    mod = inputs.get('mod', 987489)
    if M is None or n is None:
        return float('nan')
    # Generic square matrix exponentiation with modulo, return sum of entries of M^n
    k = len(M)
    def mat_mul(A, B):
        C = [[0]*k for _ in range(k)]
        for i in range(k):
            Ai = A[i]
            for t in range(k):
                if Ai[t]:
                    a = Ai[t]
                    Bt = B[t]
                    for j in range(k):
                        C[i][j] = (C[i][j] + a * Bt[j]) % mod
        return C
    def mat_pow(A, e):
        R = [[1 if i==j else 0 for j in range(k)] for i in range(k)]
        while e:
            if e & 1:
                R = mat_mul(R, A)
            A = mat_mul(A, A)
            e >>= 1
        return R
    P = mat_pow([[x % mod for x in row] for row in M], int(n))
    s = 0
    for row in P:
        s = (s + sum(row)) % mod
    return float(s)

